import data from './sampleInterviews.json';

/**
 * SYNTHETIC demo interviews (generated by scripts/generate-sample-audio.py with
 * macOS text-to-speech). All names, numbers and organizations are fictional.
 * Their transcripts are pre-written, so in demo mode they are labeled
 * "Sample transcript" rather than presented as speech-recognition output.
 */
export interface SampleInterview {
  id: string;
  title: string;
  participantLabel: string;
  audioFile: string;
  durationMs: number;
  asset: number;
  segments: { id: string; speaker: string; startMs: number; endMs: number; text: string }[];
}

const assets: Record<string, number> = {
  'clinic-scheduling': require('../../assets/audio/clinic-scheduling.wav'),
  'transit-commute': require('../../assets/audio/transit-commute.wav'),
};

export const SAMPLE_INTERVIEWS: SampleInterview[] = data.interviews.map((interview) => ({
  ...interview,
  asset: assets[interview.id],
}));

export const getSample = (id: string | undefined) => SAMPLE_INTERVIEWS.find((s) => s.id === id);

export const DEMO_PROJECT = {
  name: 'Demo: Everyday scheduling pain points',
  researchQuestion: 'How do people coordinate time-sensitive services (healthcare, transit) around work, and where do current tools break down?',
  researchContext: 'Exploratory interviews for a mobile scheduling concept. Focus on workarounds, trust, and moments of friction.',
};
